**מה הקובץ עושה** 
- מציג תעודת זהות מודרנית עם רקע גרדיאנט, תמונת פרופיל (תמונת ברירת מחדל) וכל הפרטים שהוזכרו בשיחה. 
- תומך במצב כהה/בהיר אוטומטית. 
- כולל אנימציית ריחוף קלה לשיפור חוויית המשתמש.

**הרחבות אפשריות** 
- להחליף את תמונת הפרופיל בתמונה שלך על‑ידי שינוי כתובת `background-image` ב‑`.photo`. 
- להוסיף QR‑code עם קישור למידע נוסף (למשל קובץ PDF של תעודה מלאה) בעזרת ספריית QRCode.js. 
- להוסיף כפתור “הדפס” עם `window.print()` למטרת הדפסה פיזית.

הנה אפליקציית ווב פשוטה לבניית מודלים בלגו – בחירת צבעים, הצבת קוביות על רשת, ושמירת העבודה ב‑localStorage.

```html
<!-- file: index.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<title>בוני לגו</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
 :root {
 --bg-light: #f5f7fa;
 --bg-dark: #1e1e2f;
 --primary: #4a90e2;
 --shadow: rgba(0,0,0,0.15);
 --cell-size: 30px;
 --transition: 0.2s ease;
 }
 body {
 margin:0; font-family:system-ui,Arial,sans-serif;
 background: var(--bg-light);
 color:#333;
 display:flex; flex-direction:column; align-items:center;
 min-height:100vh;
 transition: background var(--transition);
 }
 .dark-mode { background: var(--bg-dark); color:#eee; }
 h1 { margin:1rem 0; font-size:1.8rem; }
 .palette { display:flex; gap:0.5rem; margin-bottom:1rem; }
 .color-swatch {
 width: var(--cell-size); height: var(--cell-size);
 border-radius:4px; cursor:pointer; border:2px solid transparent;
 transition: border var(--transition);
 }
 .color-swatch.selected { border-color:#000; }
 .grid {
 display:grid; gap:2px;
 background:#ddd; padding:2px;
 border-radius:8px; box-shadow:0 4px 8px var(--shadow);
 }
 .cell {
 width: var(--cell-size); height: var(--cell-size);
 background:#fff; border-radius:2px;
 cursor:pointer; transition: background var(--transition);
 }
 .cell:hover { box-shadow:inset 0 0 0 2px var(--primary); }
 .controls { margin-top:1rem; display:flex; gap:0.5rem; }
 button {
 padding:0.5rem 1rem; border:none; border-radius:4px;
 background:var(--primary); color:#fff; cursor:pointer;
 transition: background var(--transition);
 }
 button:hover { background:#357ab8; }
 @media (max-width:768px) {
 :root { --cell-size:24px; }
 }
</style>
</head>
<body>
<h1>בוני לגו</h1>

<div class="palette" aria-label="פלטת צבעים">
 <div class="color-swatch selected" data-color="#ff4d4d" style="background:#ff4d4d;" aria-label="אדום"></div>
 <div class="color-swatch" data-color="#4d79ff" style="background:#4d79ff;" aria-label="כחול"></div>
 <div class="color-swatch" data-color="#4dff88" style="background:#4dff88;" aria-label="ירוק"></div>
 <div class="color-swatch" data-color="#ffd24d" style="background:#ffd24d;" aria-label="צהוב"></div>
 <div class="color-swatch" data-color="#333333" style="background:#333333;" aria-label="שחור"></div>
 <div class="color-swatch" data-color="#ffffff" style="background:#ffffff; border:1px solid #ccc;" aria-label="לבן"></div>
</div>

<div class="grid" id="legoGrid" role="grid" aria-label="רשת בניית לגו"></div>

<div class="controls">
 <button id="clearBtn">נקה הכל</button>
 <button id="themeBtn">מצב כהה/בהיר</button>
</div>

<script>
(() => {
 const rows = 16, cols = 16;
 const gridEl = document.getElementById('legoGrid');
 const palette = document.querySelectorAll('.color-swatch');
 const clearBtn = document.getElementById('clearBtn');
 const themeBtn = document.getElementById('themeBtn');
 let selectedColor = palette[0].dataset.color;

 // בניית הרשת
 const createGrid = () => {
 gridEl.style.gridTemplateColumns = `repeat(${cols}, var(--cell-size))`;
 const cells = [];
 for (let i = 0; i < rows * cols; i++) {
 const cell = document.createElement('div');
 cell.className = 'cell';
 cell.setAttribute('role', 'gridcell');
 cell.dataset.index = i;
 cell.addEventListener('click', () => paintCell(cell));
 cells.push(cell);
 gridEl.appendChild(cell);
 }
 return cells;
 };
 const cells = createGrid();

 // בחירת צבע
 palette.forEach(swatch => {
 swatch.addEventListener('click', () => {
 palette.forEach(s => s.classList.remove('selected'));
 swatch.classList.add('selected');
 selectedColor = swatch.dataset.color;
 });
 });

 // צביעת תא
 const paintCell = (cell) => {
 cell.style.background = selectedColor;
 saveState();
 };

 // שמירת מצב ב‑localStorage
 const saveState = () => {
 const state = cells.map(c => c.style.background || '');
 localStorage.setItem('legoGridState', JSON.stringify(state));
 };

 // טעינת מצב
 const loadState = () => {
 const saved = JSON.parse(localStorage.getItem('legoGridState')||'[]');
 if (saved.length === rows*cols) {
 saved.forEach((color, i) => {
 if (color) cells[i].style.background = color;
 });
 }
 };

 // ניקוי הרשת
 clearBtn.addEventListener('click', () => {
 cells.forEach(c => c.style.background = '');
 saveState();
 });

 // שינוי מצב כהה/בהיר
 themeBtn.addEventListener('click', () => {
 document.body.classList.toggle('dark-mode');
 });

 // אתחול
 loadState();
})();
</script>
